from billing import email_client, invoices


def send_invoice_email(payload):
    invoice = invoices.get(payload["invoice_id"])
    email_client.send(
        to=invoice.customer_email,
        template="invoice",
        data={"number": invoice.number, "total": invoice.total},
    )
    invoices.mark_emailed(invoice.id)


HANDLERS = {"send_invoice_email": send_invoice_email}
